    Bug 2044041 - Remove any trailing slashes from OAuth redirect target. r=mkmelin,tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D303785

diff --git a/mailnews/base/src/OAuth2.sys.mjs b/mailnews/base/src/OAuth2.sys.mjs
index 0aaccd326c5..8b6b0b7bc8a 100644
--- a/mailnews/base/src/OAuth2.sys.mjs
+++ b/mailnews/base/src/OAuth2.sys.mjs
@@ -1015,7 +1015,9 @@ class ExternalRequest {

     socket.asyncListen(listener);
     this._loopbackRedirectListener = listener;
-    this.redirectURI = callbackPrefix;
+    // URL serialisation adds "/" for an empty path, but OAuth redirect URI
+    // matching may be exact.
+    this.redirectURI = callbackPrefix.replace(/\/$/, "");
     return true;
   }
